import{_ as t,o as i,c as o,a3 as a}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"Logistics Principles and Some Terms","description":"","frontmatter":{"translationSource":{"title":"物流原理与一些名词","archivedAt":"2026-11-23","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=Ul3PjfHfEH7t9ofd3SfA1L","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/logistics-principles-and-frontier-research"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/logistics-principles-and-frontier-research"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/logistics-principles-and-frontier-research"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/logistics-principles-and-frontier-research"}]]},"headers":[],"relativePath":"logistics-principles-and-frontier-research.md","filePath":"logistics/src/page-Ul3PjfHfEH7t9ofd3SfA1L.md"}'),r={name:"logistics-principles-and-frontier-research.md"};function n(s,e,l,c,p,d){return i(),o("div",null,[...e[0]||(e[0]=[a('<div class="logistics-content"><h1 id="logistics-principles-and-some-terms" tabindex="-1">Logistics Principles and Some Terms <a class="header-anchor" href="#logistics-principles-and-some-terms" aria-label="Permalink to &quot;Logistics Principles and Some Terms&quot;">​</a></h1><p class="page-updated" data-update-status="recorded"><span>Content updated: </span><a href="/endfield-skydoc/changelog/capture-2026-11-23T06-44-45-722Z-4358a738" title="Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record." aria-label="Content updated: 2026-11-23. Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record."><time datetime="2026-11-23T06:44:47.018Z">2026-11-23</time></a><span class="page-updated-zone"> (China Standard Time)</span></p><blockquote><p>Source page ID: <code>Ul3PjfHfEH7t9ofd3SfA1L</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=Ul3PjfHfEH7t9ofd3SfA1L" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>This page is currently maintained mainly by jnk.</p><p><span id="source-block-5L4w3zMYiVCfmdi6ASRqkO"></span></p><h2 id="logistics-bug-analysis" tabindex="-1">Logistics Bug Analysis <a class="header-anchor" href="#logistics-bug-analysis" aria-label="Permalink to &quot;Logistics Bug Analysis&quot;">​</a></h2><p><a href="/endfield-skydoc/input-output-merge-priority-theory">Input / Output / Merge Priority Theory: A Brief Explanation</a></p><p><a href="/endfield-skydoc/introduction-to-analyzing-endfield-logistics-bugs">Introduction to Analyzing Endfield Logistics Bugs</a></p><p><span id="source-block-Ik2ViXezbe9d6VFUOZIUc6"></span></p><h2 id="definitions-of-various-special-structures" tabindex="-1">Definitions of Various Special Structures <a class="header-anchor" href="#definitions-of-various-special-structures" aria-label="Permalink to &quot;Definitions of Various Special Structures&quot;">​</a></h2><p><span id="source-block-f5f4WE5OyQHLDbhWbKgmAv"></span></p><h3 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h3><p>A filter in the narrow sense makes a nonuniform input sequence more uniform, for example turning 10110 10011 into 10110 10110. It is also called a <strong>flow stabilizer</strong>.</p><p>With full-belt input, equivalent to a comparatively uniform flow limiter.</p><p>Broad-sense filter: low-pass diverts sequence flow exceeding the specified flow-rate range elsewhere, usually by inserting it into a sequence below the specified flow-rate range or out of the structure. High-pass is the opposite.</p><p><span id="source-block-6wMXamjZ5Q8JK8QhmLPm7f"></span></p><h3 id="switching-detector" tabindex="-1">Switching Detector <a class="header-anchor" href="#switching-detector" aria-label="Permalink to &quot;Switching Detector&quot;">​</a></h3><p>A container that sends a temporary blocking signal upstream when the input item type changes. It usually has a large capacity.</p><p><span id="source-block-bxoKy84qBhJdi0XP4neKaG"></span></p><h4 id="pipe" tabindex="-1">Pipe <a class="header-anchor" href="#pipe" aria-label="Permalink to &quot;Pipe&quot;">​</a></h4><p>A pipe holds only one fluid type at a time. When the input changes, the next fluid waits until the last drop of the previous fluid leaves the pipe. The duration of blocking increases with pipe length.</p><p><span id="source-block-0XZQW4y0Ab7dxcTaBH1LGr"></span></p><h4 id="single-type-container" tabindex="-1">Single-Type Container <a class="header-anchor" href="#single-type-container" aria-label="Permalink to &quot;Single-Type Container&quot;">​</a></h4><p>A container that can hold only one item type. It can accept a new item type only after its existing contents leave. The duration of blocking increases with the number of items inside and decreases with the average output rate.</p><p>In one special setup, a given fluid must finish entering the container and then wait before it can start leaving. The blocking duration is proportional to the amount of that fluid in the system. A downstream transition from blocked to flowing takes a fixed time to propagate upstream.</p><p><span id="source-block-9j2XLqzFcpwJ8W5QQIYeRK"></span></p><h3 id="flow-regularizers" tabindex="-1">Flow Regularizers <a class="header-anchor" href="#flow-regularizers" aria-label="Permalink to &quot;Flow Regularizers&quot;">​</a></h3><p>Narrow-sense flow regularizer: converts the input sequence into consecutive 1/0 runs, e.g. 10110 10011 → 11100 11100.</p><p>With a full belt or excess input flow, the device sends a continuous sequence of blocking signals upstream, alternating between 1 and 0.</p><p>Broad-sense flow regularizer: converts the input flow into a specifically structured flow; typically into continuous flow alternating with 0 flow, and also into particular sequences such as perfectly uniform ones.</p><p><span id="source-block-qRQBmPKZ0UOWx8eTbhcphN"></span></p><h4 id="rectification-by-complementing-a-continuous-item-stream" tabindex="-1"><strong>Rectification by Complementing a Continuous Item Stream</strong> <a class="header-anchor" href="#rectification-by-complementing-a-continuous-item-stream" aria-label="Permalink to &quot;**Rectification by Complementing a Continuous Item Stream**&quot;">​</a></h4><p>Use a continuous stream of auxiliary items as the control input of a basic control structure. The controlled items arriving at the same time are delayed until they can pass, then pass as a continuous run. These rectifiers can fail if the outgoing line slows down and breaks up the continuous stream. There are two types.</p><p><span id="source-block-jiYkj5PpL5l2w3MFGeN0Zs"></span></p><h4 id="hourglass-rectification" tabindex="-1"><strong>Hourglass Rectification</strong> <a class="header-anchor" href="#hourglass-rectification" aria-label="Permalink to &quot;**Hourglass Rectification**&quot;">​</a></h4><p>Built using a switching detector / single-type container.</p><p><span id="source-block-dey4t7kblTAWoIHHqzUYE7"></span></p><h3 id="overflow-routers" tabindex="-1">Overflow Routers <a class="header-anchor" href="#overflow-routers" aria-label="Permalink to &quot;Overflow Routers&quot;">​</a></h3><p>Narrow-sense overflow router: the input has a strict priority relation between two output ports, that is, B receives no flow until A is too full to output.</p><p>Broad-sense overflow router: the input has a non-strict priority relation between two output ports, that is, under no-load conditions the flow output toward the high-priority direction A is greater than A&#39;s maximum passable flow rate when fully loaded.</p><p><span id="source-block-n9B7tFb0RiVmFdwgWv9DxN"></span></p><h3 id="flow-limiters" tabindex="-1">Flow Limiters <a class="header-anchor" href="#flow-limiters" aria-label="Permalink to &quot;Flow Limiters&quot;">​</a></h3><p>A single-inlet, single-outlet logistics structure that limits the upper bound of the average flow rate passing through it and does not guarantee a specific output sequence. Sometimes also called a rate limiter.</p><p><span id="source-block-feYWNsMRluyjDzYHJU8HVp"></span></p><h3 id="overflow-devices-priority-output-devices" tabindex="-1">Overflow Devices / Priority-Output Devices <a class="header-anchor" href="#overflow-devices-priority-output-devices" aria-label="Permalink to &quot;Overflow Devices / Priority-Output Devices&quot;">​</a></h3><p>A logistics structure with one input and two outputs.</p><p>An overflow device or priority output device in the narrow sense routes input during a time window to the higher-priority output whenever that output is flowing, leaving the low-priority outlet idle. With a full-belt input it can also act as a <strong>flow duplicator</strong>. Apply a blocking signal to its high-priority side and the low-priority output emits items for the same duration.</p><p>Broadly defined overflow / priority-output device: assume the outputs divide flow in fixed proportions while all are flowing. For the long-term average input, after this proportional allocation, the high-priority direction consumes less than the total flow allocated to it. Before that direction stops flowing, output remains proportional regardless of the nominal priority. Once material accumulates there until it stops flowing, however, the structure has the same effect as the narrowly defined version.</p><p><span id="source-block-gk0ftJwaqdj335twrpq0qB"></span></p><h3 id="priority-convergers" tabindex="-1">Priority Convergers <a class="header-anchor" href="#priority-convergers" aria-label="Permalink to &quot;Priority Convergers&quot;">​</a></h3><p>Narrowly defined priority Converger: a Splitter → Converger; conveyor → Converger structure built on merge priority. Since total flow is at most 1, when the high-priority direction supplies flow 1, the low-priority direction falls to flow 0 and is &quot;cut off.&quot;</p><p>Broadly defined priority Converger: similarly to the broadly defined priority-output device, it is sufficient to guarantee that one input remains unblocked once output reaches a specified level.</p><p><span id="source-block-Tr4QvYq1Ruz7WvejwO5RcS"></span></p><h3 id="screeners-filters-sorters-separators" tabindex="-1">Screeners \\ Filters \\ Sorters \\ Separators <a class="header-anchor" href="#screeners-filters-sorters-separators" aria-label="Permalink to &quot;Screeners \\ Filters \\ Sorters \\ Separators&quot;">​</a></h3><p>References within this section always use the name sorter. In essence this is a splitter→a container that can accept only a certain fluid \\ item; the container is usually a filtering control port. When there are special requirements (压元件 “reducing the component count”, 压地 “reducing the footprint”), devices such as pipes \\ conduits that can store only one kind of fluid, or the activator port of the Solid-Gas \\ Fluid-Gas Transmuting Unit that accepts only activators, are used instead of a container.</p><p><span id="source-block-TwAdfmWti8bBHTAGCmTcqt"></span></p><h3 id="basic-control-structure" tabindex="-1">Basic Control Structure <a class="header-anchor" href="#basic-control-structure" aria-label="Permalink to &quot;Basic Control Structure&quot;">​</a></h3><p>The basic control structure has two inputs and two outputs, with each input corresponding to one output. Of the two inputs, one is the control branch and the other the controlled branch. A control-branch flow of 1 cuts off the controlled branch. The basic control structure assumes flowing outputs.</p><p><span id="source-block-msCpcnAU4hdiRv7T0efvi5"></span></p><h4 id="solid-solid-liquid-liquid-basic-control-structure" tabindex="-1">Solid-Solid \\ Liquid-Liquid Basic Control Structure <a class="header-anchor" href="#solid-solid-liquid-liquid-basic-control-structure" aria-label="Permalink to &quot;Solid-Solid \\ Liquid-Liquid Basic Control Structure&quot;">​</a></h4><p>The usual implementation is priority converger→sorter, which ensures that both inputs and outputs are of exactly two pure kinds, while the characteristics of the priority converger make one input control the other input. The overall effect is similar to a priority converger, except that the outputs are of multiple kinds.</p><p><span id="source-block-WAa6YT2JcwqSHP14sGqTCT"></span></p><h4 id="solid-liquid-basic-control-structure" tabindex="-1">Solid-Liquid Basic Control Structure <a class="header-anchor" href="#solid-liquid-basic-control-structure" aria-label="Permalink to &quot;Solid-Liquid Basic Control Structure&quot;">​</a></h4><p>Usual implementation 1: an unpowered reaction tank can accept both solids and liquids, allowing their amounts to rise and fall together (in the same slot). Combined with an inverter, this implements the basic control structure. Likewise, facilities with a recipe that uses both liquid and solid inputs can directly make the two amounts rise and fall together.</p><p><span id="source-block-XKuBsS73GKwpAOmtYCmWDS"></span></p><h3 id="reversed-basic-control-structure-fixed-ratio-converger" tabindex="-1">Reversed Basic Control Structure / Fixed-Ratio Converger <a class="header-anchor" href="#reversed-basic-control-structure-fixed-ratio-converger" aria-label="Permalink to &quot;Reversed Basic Control Structure / Fixed-Ratio Converger&quot;">​</a></h3><p>The reversed basic control structure also has two inputs and two outputs, but its control and controlled branches are on the output side. It assumes blocked (sufficiently supplied) inputs. Unlike a broadly defined Converger, which merges the same fluid, the reversed basic control structure keeps the two outputs in the same proportion.</p><p><span id="source-block-43mxU8WxSkD6eR8LkKUVn8"></span></p><h3 id="inverter" tabindex="-1">Inverter <a class="header-anchor" href="#inverter" aria-label="Permalink to &quot;Inverter&quot;">​</a></h3><p>A logistics structure with two inputs and two outputs. One input/output pair forms the control branch; the other forms the controlled branch.</p><p>Its rough structure is:</p><p>Controlled input — low-priority merge &gt; priority Converger → flow limiter → priority-output device — low-priority output (overflow) → controlled output;</p><p>Priority-output device — high-priority output — controlled branch → control structure — controlled material — high-priority merge → priority Converger;</p><p>Control input → control structure → control output</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-d642b938a9367404.q90-d9ae26130ec77849.webp" alt="Logistics Principles and Some Terms"></p><p>Whenever the control structure is controlled into producing output, the controlled branch correspondingly produces none. This inverts the control structure&#39;s result, hence “inverter”; different control structures give different effects.</p><p>The figure shows a common result, typically called Cuprium Gas liquid-to-gas feedforward. It lowers the Xiragen feed when the Cuprium Gas input is insufficient.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-84ea65b05b721d23.q90-b587c317b2f3d88e.webp" alt="Logistics Principles and Some Terms"></p><p>With a reversed basic control structure, setting the control output to a specific rate limit can fix the sum of the control output and the controlled output. In some cases this behaves like a priority architecture.</p><p><span id="source-block-S8PWbXu9lpMq8KlwIZxgRB"></span></p><h3 id="continuous-gap-generator-continuous-item-generator" tabindex="-1">Continuous Gap Generator / Continuous Item Generator <a class="header-anchor" href="#continuous-gap-generator-continuous-item-generator" aria-label="Permalink to &quot;Continuous Gap Generator / Continuous Item Generator&quot;">​</a></h3><p>A component that outputs a run of gaps or items after receiving a signal. Input and output counts usually vary.</p><p><span id="source-block-rF768UficaFulfX1mHS9yR"></span></p><h4 id="odd–even-delay" tabindex="-1">Odd–Even Delay <a class="header-anchor" href="#odd–even-delay" aria-label="Permalink to &quot;Odd–Even Delay&quot;">​</a></h4><p>Delay the auxiliary item by 1 tile so it competes with the target item that would have occupied that tile. The target-item direction has previously sent material through at full belt. At the merge, the auxiliary item goes first and the target item is held back by one tile, creating an extra gap ahead of the auxiliary item. Stacking n copies of the structure produces n+1 consecutive gaps.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-5b646c09003ea60c.q90-6a93481adb9455c8.webp" alt="Logistics Principles and Some Terms"></p><p><span id="source-block-ZZSfbctDNK0aQpPr2myvCj"></span></p><h4 id="switching-detection" tabindex="-1">Switching Detection <a class="header-anchor" href="#switching-detection" aria-label="Permalink to &quot;Switching Detection&quot;">​</a></h4><p>When a single-type container switches, it sends upstream a blocking signal corresponding to the N items it holds. A flow duplicator or priority output device converts the signal into a run of N items. Merging adds 1 more item of blocking, so the final output is N+1.</p><p>To remove the extra 1, use a basic control structure to subtract one auxiliary item as it enters, bringing output back to N.</p><p>The single-type container empties after switching, so return the N output items after using them. Use a basic control structure to convert the run of auxiliary items into a run of gaps on the target belt, then return the auxiliary items to the container.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-8be9051d5255768a.q90-690009b5c61cd79f.webp" alt="Logistics Principles and Some Terms"></p><div class="logistics-image-caption" data-source-block="HNJmbzpnnP9zAmoNtsjM64"><p>Each edge here is a single conveyor belt.</p></div><p><span id="source-block-wO7xPIiHDJwfeAtqFW4VJE"></span></p><h2 id="uniformity-and-range" tabindex="-1">Uniformity and Range <a class="header-anchor" href="#uniformity-and-range" aria-label="Permalink to &quot;Uniformity and Range&quot;">​</a></h2><p><span id="source-block-BKd0bfBqMQYjGOon5TjRNh"></span></p><h3 id="uniform-binary-splitters" tabindex="-1">Uniform Binary Splitters <a class="header-anchor" href="#uniform-binary-splitters" aria-label="Permalink to &quot;Uniform Binary Splitters&quot;">​</a></h3><details><summary><span class="mark-grey">How Bresenham&#39;s Algorithm Works</span></summary><p>Ideally the total item count is proportional to time, n=Kt. In practice n and t must be integers. Maintain an output discrepancy a. Each time step the ideal count rises by K, so add K to a. If the discrepancy after adding K exceeds 1, output an item and subtract 1 from the discrepancy to bring it back below 1.</p></details><p><span id="source-block-NOQ4vy8rsvDM9q7qet2tpl"></span></p><h4 id="edwardkerman-s-design" tabindex="-1">EdwardKerman&#39;s Design <a class="header-anchor" href="#edwardkerman-s-design" aria-label="Permalink to &quot;EdwardKerman&#39;s Design&quot;">​</a></h4><p><span class="mark-grey">#jnk: I doubt there&#39;s another form, haha.</span></p><p><a href="http://www.bilibili.com/video/BV17tfVBmE8v" target="_blank" rel="noreferrer">Bilibili video</a></p><p>Starting with Bresenham&#39;s algorithm, let K=p/q and q=2^n. Set n&#39;=q<em>n=pt and track a&#39;=q</em>a, which grows by p each time step. When a&#39; exceeds q, output one item and subtract q from a&#39;.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-d695c7ebe8947225.q90-1147c35141249a34.webp" alt="Logistics Principles and Some Terms"></p><p>Consider a simplified model without phase alignment, with p=(0011)_2 and q=2^4. For a&#39;, a splitter pointing right represents 0 and one pointing across represents 1. The two belts carry the carry bit: 1 on top and 0 below.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-1726a7669abd46bb.q90-db2d5200ccfdea4b.webp" alt="Logistics Principles and Some Terms"></p><p>For each bit, the addition is carry-in + p + a&#39; = a&#39; + carry-out.</p><p>0+0+0=0: the item enters on the lower belt, with the splitter above and pointing right. The item stays on the lower belt and the splitter stays unchanged.<br> 0+1+0=1: the item and the splitter are below, and the splitter points right. The item stays below (no carry) and the splitter changes.<br> 0+1+1=0+1: the item and splitter are below, and the splitter points upward. The output item goes above (carry) and the splitter changes (0 becomes 1).</p><p>The same logic covers all eight combinations. One input item implements a&#39;+p. A carry-out of 1 indicates that the value has exceeded q (a&#39;&gt;q) and one item is output.</p><p>When items enter continuously, each path from the input to a given point must have the same length. This prevents two items from reaching that point simultaneously and interfering with the calculation.</p><p><span id="source-block-rJLuoyW0sbNOPnKggEQMI8"></span></p><h3 id="uniformity-of-simple-rational-splitters" tabindex="-1">Uniformity of Simple Rational Splitters <a class="header-anchor" href="#uniformity-of-simple-rational-splitters" aria-label="Permalink to &quot;Uniformity of Simple Rational Splitters&quot;">​</a></h3><p><span class="mark-grey">#jnk: I don&#39;t know this part. I&#39;ll leave it to 早色芋 or Cipolla_, haha.</span></p><p><span id="source-block-saFuJ384PvuWkO0x5E0uld"></span></p><h3 id="uniform-rational-flow-limiters" tabindex="-1">Uniform Rational Flow Limiters <a class="header-anchor" href="#uniform-rational-flow-limiters" aria-label="Permalink to &quot;Uniform Rational Flow Limiters&quot;">​</a></h3><p><span id="source-block-Uj5kS4ulgYdVqCL6baJ4Ku"></span></p><h4 id="leap-year-algorithm" tabindex="-1">Leap-Year Algorithm <a class="header-anchor" href="#leap-year-algorithm" aria-label="Permalink to &quot;Leap-Year Algorithm&quot;">​</a></h4><p><span id="source-block-xQRRd0h5FlKNP3iUeDlYjq"></span></p><h2 id="logistics-theory-for-idealized-systems" tabindex="-1">Logistics Theory for Idealized Systems <a class="header-anchor" href="#logistics-theory-for-idealized-systems" aria-label="Permalink to &quot;Logistics Theory for Idealized Systems&quot;">​</a></h2><p>See <a href="/endfield-skydoc/flow-theory-for-idealized-logistics-systems">Flow Theory for Idealized Logistics Systems</a> for the full treatment. The notes below are introductory and have only been partially checked.</p><p><span id="source-block-cHTDahDFpgGCpDwr4dbuTD"></span></p><h3 id="what-an-idealized-system-is-and-what-it-can-do" tabindex="-1">What an Idealized System Is and What It Can Do <a class="header-anchor" href="#what-an-idealized-system-is-and-what-it-can-do" aria-label="Permalink to &quot;What an Idealized System Is and What It Can Do&quot;">​</a></h3><p>An idealized system is a directed graph with a capacity on each edge. It corresponds in certain respects to a network of Endfield logistics components and conveyor belts. The correspondence lets us <em><strong>study</strong></em> the discrete logistics network using a continuous model, <strong>calculate</strong> flows through structures, <strong>design</strong> a graph for target inputs and outputs and turn it into a logistics layout, <strong>prove</strong> results such as existence and uniqueness of a steady state, and <strong>explain</strong> why specific flows arise.</p><p><span id="source-block-gxkkNKNrBqUpClRYQfGYUv"></span></p><h4 id="definitions" tabindex="-1">Definitions <a class="header-anchor" href="#definitions" aria-label="Permalink to &quot;Definitions&quot;">​</a></h4><p>There are four kinds of nodes: inputs (source storage feeding the network), outputs (destination storage receiving flow from the network), split nodes (corresponding to splitters), and merge nodes.</p><p>We are concerned with steady state. Most definitions below refer to node and edge states at steady state and may not apply during transients.</p><p>A port on a node, corresponding to an incident edge, can be <strong>polling</strong> or <strong>nonpolling</strong>. <span class="mark-grey">The extended idealized system (++) also has a high-priority state, which is outside this discussion.</span><br> At a polling port, there is always an item to take or a gap to fill when it is polled. For example, two polling outputs on a splitter are each free to accept an item whenever their turn comes.<br> A nonpolling port can still be polled, but there are occasions when it cannot transfer an item. For example, feed a two-way splitter from a full belt and place a 1/5 limiter on one output. That output is polled in 1/2 of cases, yet cannot always accept an item, so it is nonpolling.</p><p>An edge can be <strong>blocked</strong> or <strong>flowing</strong>. Its three cases are nonflowing, both blocked and flowing, or nonblocked. Full and empty belts are special cases. <span class="mark-grey">A full belt is packed with items, and an empty belt has none.</span><br> A blocked edge has a polling downstream port. Its stock stays high enough for the downstream node to take an item whenever it wants one.<br> A flowing edge has a polling upstream port. Its stock stays low enough for there to be room whenever upstream sends an item.<br> On a nonflowing edge, stock builds until the belt fills. On a nonblocked edge, stock drains until the belt empties. Each case corresponds to the nonpolling state on one end. On an edge that is both blocked and flowing, stock stays at a constant level between full and empty, with both ends polling. The case in which both ends are nonpolling is undefined and does not normally occur.</p><p><span id="source-block-CZFzmIr2D0AzZbwvw5p6Qa"></span></p><h3 id="rules-of-the-three-state-model" tabindex="-1">Rules of the Three-State Model <a class="header-anchor" href="#rules-of-the-three-state-model" aria-label="Permalink to &quot;Rules of the Three-State Model&quot;">​</a></h3><p>The three edge states define the three-state model. Of the equivalent models these definitions give us, this one makes the physical correspondence especially clear: look at how many items are on the edge.</p><p><strong>Basic requirements.</strong> Conserve flow. By default, an edge that is both blocked and flowing has flow 1. An edge cannot be both nonflowing and nonblocked.<br><strong>Boundary states.</strong> The outgoing edges of inputs are blocked, and the incoming edges of outputs are flowing.<br><strong>Equal allocation at nodes.</strong> The flowing outputs of a split node have equal rates, and the blocked inputs of a merge node have equal rates.<br><strong>Rates by state.</strong> A split node&#39;s blocked outputs carry no more flow than its flowing outputs [0]. A merge node&#39;s flowing inputs carry no more flow than its blocked inputs.<br><strong>Propagation.</strong> A split node has a flowing output if and only if its input is flowing [1]. Its input is blocked if and only if all outputs are blocked. A merge node has a blocked input if and only if its output is blocked. Its output is flowing if and only if all inputs are flowing. <span class="mark-grey">Equivalently, a node has a flowing output if and only if all inputs are flowing, and it has a blocked input if and only if all outputs are blocked.</span><br> Here is where [0] and [1] come from. You can work through the rest yourself.<br> [0] Return to the two-way splitter fed by a full belt. Normally each output gets half. A limited branch can&#39;t accept its half, so the splitter polls the next output for each rejected item. Items originally destined for the limited branch go to the other branch, leaving the limited branch with the lower rate.<br> [1] If a split node has a flowing output, it can poll that output to pass along items held up elsewhere. Items don&#39;t back up inside it, so it can keep accepting upstream input, which leaves upstream nonblocked.</p><p>The three-state model provides a consistency check for computed flows and can be used with MILP to solve for flows through particular structures.</p></div>',1)])])}const f=t(r,[["render",n]]);export{h as __pageData,f as default};
